CREATE TABLE "groups" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "emoji" TEXT NULL, "color_value" INTEGER NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'VND', "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "members" ("id" TEXT NOT NULL, "group_id" TEXT NOT NULL REFERENCES "groups" (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "avatar_color_value" INTEGER NOT NULL, "emoji" TEXT NULL, "is_me" INTEGER NOT NULL DEFAULT 0 CHECK ("is_me" IN (0, 1)), "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "expenses" ("id" TEXT NOT NULL, "group_id" TEXT NOT NULL REFERENCES "groups" (id) ON DELETE CASCADE, "title" TEXT NOT NULL, "amount_cents" INTEGER NOT NULL, "currency_code" TEXT NOT NULL, "paid_by_member_id" TEXT NOT NULL REFERENCES members (id), "split_type" TEXT NOT NULL, "category" TEXT NOT NULL DEFAULT 'other', "note" TEXT NULL, "expense_date" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "expense_splits" ("id" TEXT NOT NULL, "expense_id" TEXT NOT NULL REFERENCES expenses (id) ON DELETE CASCADE, "member_id" TEXT NOT NULL REFERENCES members (id), "value" INTEGER NOT NULL, "amount_cents" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "settlements" ("id" TEXT NOT NULL, "group_id" TEXT NOT NULL REFERENCES "groups" (id) ON DELETE CASCADE, "from_member_id" TEXT NOT NULL REFERENCES members (id), "to_member_id" TEXT NOT NULL REFERENCES members (id), "amount_cents" INTEGER NOT NULL, "currency_code" TEXT NOT NULL, "note" TEXT NULL, "settled_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
